"""Página pública de atribuição; não carrega novamente as fotografias."""
import html,json
from pathlib import Path
from site_policies import protect
ROOT=Path(__file__).resolve().parent.parent
registry=json.loads((ROOT/'dados/licencas-imagens.json').read_text(encoding='utf-8'))
esc=lambda s:html.escape(str(s),quote=True)
blocks=[]
for row in registry['images']:
    source=f'<a href="{esc(row["page"])}" rel="noopener noreferrer">Arquivo e fonte</a>'
    license=f'<a href="{esc(row["licenseUrl"])}" rel="license noopener noreferrer">{esc(row["license"])}</a>' if row['licenseUrl'] else esc(row['license'])
    scope='' if row.get('active') else '<p>Acervo técnico sem uso nas páginas atuais.</p>'
    blocks.append(f'<article id="{row["id"]}"><h2>{esc(row["title"])}</h2><p>{esc(row["author"])}</p><p>{source} · {license}</p><p>{esc(row["sourceCredit"])}</p><p>{esc(row["changes"])}</p><p>{esc(row["conditions"])}</p><p>{esc(row.get("basis",""))}</p>{scope}</article>')
page='''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Créditos das imagens | O Peso da Camisa</title><meta name="description" content="Autoria, fontes, licenças e condições de uso das imagens do site O Peso da Camisa."><link rel="canonical" href="https://dacamisaopeso-art.github.io/o-peso-da-camisa/creditos-imagens.html"><style>body{background:#080b0e;color:#eee;font:16px/1.7 Arial,sans-serif;margin:0}main{max-width:950px;margin:auto;padding:24px}a{color:#d8a83e}article{border-top:1px solid #30363b;padding:22px 0;overflow-wrap:anywhere;scroll-margin-top:24px}h1{font-size:clamp(30px,5vw,48px)}h2{font-size:20px}p{margin:10px 0}.notice{border:1px solid #665128;padding:18px}</style></head><body><main><a href="./">← O Peso da Camisa</a><h1>Créditos das imagens</h1><p>Fotografias, bandeiras e ilustrações utilizadas no site. Conferência: 16/10/2026. Cada fotografia possui fonte e declaração de direitos próprias; estar no Wikimedia Commons não substitui essa conferência.</p><div class="notice"><p>As licenças CC BY e CC BY-SA permitem uso comercial com as respectivas condições. Adaptações de imagens CC BY-SA mantêm a mesma licença ou uma compatível; isso não estende essa licença automaticamente ao texto editorial ou ao site inteiro. O recorte visual responsivo das capas é indicado junto às imagens.</p><p>As fotografias não significam apoio de seus autores ou das pessoas retratadas ao site. Direitos de imagem, marcas e outros direitos independentes permanecem aplicáveis. Declarações de domínio público podem depender do país.</p></div><h2>Identificações dos jogos</h2><p>Os 151 símbolos do Desafio da Champions são identificações geométricas originais OPC com siglas dos clubes; não são escudos oficiais. Os emblemas da Escalação Histórica e os retratos de iniciais da Carreira também são artes de identificação do projeto.</p><h2>Bandeiras atuais</h2><p>As bandeiras atuais são fornecidas pelo <a href="https://flagcdn.com/">FlagCDN</a>, serviço do Flagpedia. O fornecedor declara as imagens em <a href="https://flagpedia.net/terms">domínio público</a>, com <a href="https://flagpedia.net/download/icons">uso comercial permitido</a>. Restrições próprias de símbolos nacionais continuam aplicáveis. Bandeiras históricas locais estão discriminadas abaixo.</p><h2>Prévia de documentários e Shorts</h2><p>As antigas capas vetoriais de vídeos e do Re-Pa permanecem no acervo técnico como ilustrações originais. As capas fotográficas atuais têm autoria, fonte e licença nos registros abaixo. O banner das Lendas continua sendo ilustração original, sem representar uma partida. Os vídeos e links originais foram preservados; a licença de uma capa não concede direitos sobre o conteúdo audiovisual acessado no YouTube.</p>'''+''.join(blocks)+'''<p><a href="./">← Voltar ao site</a></p></main></body></html>'''
(ROOT/'creditos-imagens.html').write_text(protect(page),encoding='utf-8',newline='\n')
print('Página de créditos gerada:',len(blocks),'registros.')
